import {FOODS,SLOTS,GOALS,DEFAULT_PROFILE,dateKey,shiftDate,dayIndex,validateProfile,targets,dayPlan,grocery,replacementOptions,mealOptions,workout,streak,consumed,mentor} from './engine.js';
const $=s=>document.querySelector(s),KEY='forma.v1';
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',leaf:'M20 3C9 2 3 7 5 14s12 7 15-11ZM5 20l9-10',weight:'M6 7v10M3 9v6M18 7v10M21 9v6M6 12h12',chart:'M4 3v17h17M7 14l4-5 4 3 5-7',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2',arrow:'M5 12h14m-5-5 5 5-5 5',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',drop:'M12 3c-3 5-7 9-7 13a7 7 0 0 0 14 0c0-4-4-8-7-13Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M19 5l-1 1M6 18l-1 1',moon:'M20 15A9 9 0 0 1 9 3 9 9 0 1 0 20 15Z',fire:'M13 2c2 7-4 6-2 12 2-1 3-3 3-5 8 7 5 13-2 13S1 15 8 8c-1 4 1 5 2 5-1-4 4-6 3-11Z',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',bag:'M5 7h14l2 14H3L5 7ZM8 8V6a4 4 0 0 1 8 0v2',swap:'M3 7h17l-4-4M21 17H4l4 4',close:'m6 6 12 12M18 6 6 18',download:'M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4',heart:'M12 21 3 12C-3 4 7-1 12 6c5-7 15-2 9 6Z',steps:'M8 3c-2 0-3 4-2 6s4 2 4-1-1-5-2-5ZM7 13v4M16 8c-2 0-3 4-2 6s4 2 4-1-1-5-2-5ZM15 18v4',camera:'M3 7h5l2-3h4l2 3h5v14H3ZM16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3ZM12 6v16'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.spark}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('en-IN'),cap=s=>s[0].toUpperCase()+s.slice(1),displayDate=(key,opts={day:'numeric',month:'short'})=>new Date(key+'T12:00:00').toLocaleDateString('en-IN',opts);
let state={version:1,profile:null,logs:{},measurements:[],photos:[],swaps:{},groceryChecked:{},started:dateKey()};
let storageError=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!validBackup(parsed))throw Error('invalid');state=parsed;}}catch{storageError=true;}
let route=location.hash.slice(1)||'dashboard',selectedDate=dateKey(),setupStep=0,draft=null,timerEnd=0,timerInterval,modalContext=null;
function today(){return dateKey();}
function p(){return state.profile||DEFAULT_PROFILE;}
function log(key=today()){return state.logs[key]||{food:[],water:0,steps:0,sleep:0,exercise:[],workout:false};}
function mutateLog(fn,key=today()){state.logs[key]??={food:[],water:0,steps:0,sleep:0,exercise:[],workout:false};fn(state.logs[key]);save();render();}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Storage is full or unavailable. Export a backup before leaving.');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function previous(key){return state.logs[shiftDate(key,-1)]?.checkin;}
function plan(key=today()){return dayPlan(p(),key,state.swaps[key]||{},previous(key));}
function btn(label,action,cls='secondary',attrs=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;}
function progress(value,target,cls=''){return `<div class="bar ${cls}"><span style="width:${Math.max(0,Math.min(100,value/Math.max(1,target)*100))}%"></span></div>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${text}</p>${action}</div>`;}
function plate(){return `<div class="plate-art" aria-hidden="true"><div class="plate"><div class="rice-grains"></div><div class="dal"></div><div class="greens"><i></i><i></i><i></i><i></i><i></i></div><div class="tomatoes"><b></b><b></b><b></b></div><div class="lemon"></div></div><span class="plate-label">Everyday food. Real progress.</span></div>`;}
function shell(content){const nav=[['dashboard','grid','My day'],['meals','leaf','Nutrition'],['workouts','weight','Training'],['progress','chart','My progress'],['mentor','spark','My mentor']];return `<aside class="sidebar"><a class="brand" href="#dashboard"><span class="brandmark">f</span>forma<span class="brand-dot">.</span></a><div class="side-caption">YOUR EVERYDAY COMPANION</div><nav aria-label="Main navigation">${nav.map(([id,ic,label])=>`<a href="#${id}" class="nav-link ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${route===id?'<b class="nav-dot"></b>':''}</a>`).join('')}</nav><div class="sidebar-note">${icon('leaf')}<p>Small steps.<br><strong>Stronger you.</strong></p><span>Your pace. Your progress.</span></div><a href="#settings" class="nav-link settings-link ${route==='settings'?'active':''}">${icon('settings')}<span>Profile & settings</span></a><div class="profile-chip"><span class="avatar">${esc((p().name||'Y').slice(0,1).toUpperCase())}</span><div><strong>${esc(p().name||'Your journey')}</strong><small>${GOALS[p().goal]} journey</small></div></div></aside><div class="workspace"><header class="topbar"><div><span class="green-dot"></span> A little better, every day</div><div class="topbar-right"><span>${displayDate(today(),{weekday:'short',day:'numeric',month:'short'})}</span><button class="streak-pill" data-action="streak">${icon('fire')} ${streak(state.logs,today())} day streak</button><button class="avatar small" data-action="profile" aria-label="Edit profile">${esc((p().name||'Y').slice(0,1).toUpperCase())}</button></div></header><main id="main" tabindex="-1">${content}<footer>Made for your real life. Built around your everyday wins.<span>Private to this browser · <a href="#settings">Back up your progress</a></span></footer></main></div>`;}
function title(eyebrow,heading,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p>${sub}</p></div>${action}</div>`;}
function render(){if(!state.profile){renderWelcome();return;}if(!['dashboard','meals','workouts','progress','mentor','settings'].includes(route))route='dashboard';const views={dashboard:dashboard,meals:nutrition,workouts:training,progress:progressPage,mentor:mentorPage,settings:settings};$('#app').innerHTML=shell(views[route]());}
function renderWelcome(){$('#app').innerHTML=`<div class="welcome"><header><a class="brand" href="#"><span class="brandmark">f</span>forma.</a><span class="tag">Built for your everyday</span></header><main id="main" class="welcome-grid"><section><div class="eyebrow">A PERSONAL TRANSFORMATION COMPANION</div><h1>Your next chapter.<br><em>A stronger you.</em></h1><p>Food you love. Movement that fits. A little guidance, every day. Let’s build a healthier life around you.</p><div class="welcome-actions">${btn('Build my personal plan '+icon('arrow'),'setup','primary')}${btn('Restore a backup','restore','ghost')}</div><div class="welcome-features"><span>${icon('leaf')} Indian meals</span><span>${icon('weight')} Home workouts</span><span>${icon('heart')} Your pace</span></div><small>Your data stays in this browser. No account or paid subscription needed.</small></section><section class="welcome-visual">${plate()}<div class="floating-note">${icon('check')} A plan that fits your life <small>Personalized • Practical • Budget-conscious</small></div><div class="welcome-card"><span class="eyebrow">THE FORMA APPROACH</span><h2>Less guesswork.<br>More good days.</h2><p>Plan → Practice → Reflect → Grow</p></div></section></main><div class="welcome-bottom">For adults 18–80. Wellness guidance, not medical treatment. <button class="text-btn" data-action="method">How plans are made ${icon('arrow')}</button></div></div>`;}
function dashboard(){const t=targets(p()),d=log(),used=consumed(d),pl=plan(),w=workout(p(),today(),previous(today())),m=mentor(p(),state.logs,today()),done=d.food.filter(x=>x.slot).map(x=>x.slot),next=pl.meals.find(x=>!done.includes(x.slot));
 return title('YOUR DAILY RESET',`Let’s make today count${p().name?', '+esc(p().name):''}.`,'You don’t need a perfect day. Just a few good choices.',btn(icon('plus')+' Daily check-in','checkin','primary'))+
 `<div class="dashboard-grid"><section class="hero"><div class="hero-copy"><span class="hero-badge">${icon('spark')} YOUR PLAN, YOUR PACE</span><h2>Progress starts with<br>what you do <em>today.</em></h2><p>${esc(t.limited?'Keep track of the habits that make you feel good.':`${GOALS[p().goal]} · ${p().diet==='nonveg'?'Non-vegetarian':p().diet==='eggetarian'?'Eggetarian':'Vegetarian'} meals · ${p().time}-min movement`)}</p><button class="btn lime" data-action="eat">What should I eat now? ${icon('arrow')}</button></div>${plate()}</section><section class="mentor-mini"><div class="section-kicker">${icon('spark')} A NOTE FROM YOUR MENTOR</div><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p><a class="text-link" href="#mentor">A little more guidance ${icon('arrow')}</a></section></div>
 ${t.limited?limitedNotice():''}<div class="section-head"><h2>Your daily essentials</h2><span>Small actions, meaningful change</span></div><div class="stats-grid">${stat('fire','Calories',fmt(used.k),t.calories?`/ ${fmt(t.calories)} kcal`:'kcal logged',used.k,t.calories||1,'peach',t.calories?`${fmt(Math.max(0,t.calories-used.k))} kcal remaining`:'Habit tracking mode')}${stat('leaf','Protein',used.p,t.protein?`/ ${t.protein} g`:'g logged',used.p,t.protein||1,'green','Build strength, meal by meal')}${stat('drop','Water',(d.water/1000).toFixed(2),t.water?`/ ${(t.water/1000).toFixed(2)} L`:'L logged',d.water,t.water||2500,'blue',`${btn('−','water','icon-btn','data-amount="-250" aria-label="Remove 250 ml water"')}${btn('+ 250 ml','water','mini','data-amount="250"')}`)}${stat('steps','Steps',fmt(d.steps),`/ ${fmt(p().steps)}`,d.steps,p().steps,'purple',btn('Update steps '+icon('plus'),'habits','text-btn'))}</div>
 <div class="two-columns"><section class="card"><div class="section-head"><h2>On your plate today</h2><a class="text-link" href="#meals">View plan ${icon('arrow')}</a></div>${next?`<div class="meal-feature"><div class="food-illustration ${next.slot}">${foodEmoji(next.name)}</div><div><span class="eyebrow">UP NEXT · ${next.slot.toUpperCase()}</span><h3>${next.name}</h3><p>${next.k} kcal <span class="dot">·</span> ${next.p} g protein <span class="dot">·</span> ~₹${next.price}</p><button class="text-link" data-action="recipe" data-slot="${next.slot}" data-date="${today()}">See your meal ${icon('arrow')}</button></div></div>`:empty(t.limited?'Your meals, at your pace':'You’ve made room for every meal.',t.limited?'Log your own food and follow your clinician’s plan.':'Your planned meals are logged. Add anything else you eat using the food log.') }<div class="meal-timeline">${SLOTS.map((s,i)=>`<div class="${done.includes(s)?'done':''}"><span>${done.includes(s)?icon('check'):'0'+(i+1)}</span><small>${cap(s)}</small></div>`).join('')}</div></section><section class="card workout-preview"><div class="section-head"><h2>Make time for movement</h2><span class="tag">${p().level}</span></div><div class="workout-feature"><div class="workout-art">${icon(w.rest?'leaf':'weight')}</div><div><span class="eyebrow">${w.rest?'RECOVER & RECHARGE':'TODAY’S SESSION'}</span><h3>${w.title}</h3><p>${w.minutes} min <span class="dot">·</span> ${w.rest?'Easy pace':`${w.exercises.length} exercises · ${p().equipment}`}</p></div></div><div class="workout-footer"><span>${d.workout?icon('check')+' Session logged':'Show up for yourself. That’s a win.'}</span><a class="btn secondary" href="#workouts">${w.rest?'View recovery':'Let’s move'} ${icon('arrow')}</a></div></section></div>
 <div class="two-columns bottom-grid"><section class="card"><div class="section-head"><h2>A little more balance</h2>${btn('Update','habits','text-btn')}</div><div class="balance-row"><span class="soft-icon purple">${icon('moon')}</span><div><strong>Sleep & recovery</strong><p>${d.sleep?`${d.sleep} hours logged`:'No sleep logged yet'} · Aim: ${p().sleep} h</p></div><span class="balance-value">${d.sleep||'—'} <small>h</small></span></div>${progress(d.sleep,p().sleep,'purple')}</section><section class="card checkin-card"><span class="soft-icon green">${icon('heart')}</span><div><h3>How are you really feeling?</h3><p>${d.checkin?'Check-in saved. Your next day will reflect it.':'Your energy matters as much as your numbers.'}</p></div>${btn(icon('arrow'),'checkin','round','aria-label="Open daily check-in"')}</section></div>`;
}
function stat(ic,label,value,unit,n,total,cls,foot){return `<section class="stat card"><div class="stat-head"><span>${label}</span><span class="soft-icon ${cls}">${icon(ic)}</span></div><div class="stat-value">${value} <small>${unit}</small></div>${progress(n,total,cls)}<div class="stat-foot">${foot}</div></section>`;}
function limitedNotice(){return `<div class="notice">${icon('heart')} <div><strong>Habit tracking mode</strong><p>Personalized nutrition and training targets are paused for your health context or a low current/target BMI. A qualified professional can help set an appropriate plan. You can still log meals, movement, sleep and progress.</p></div></div>`;}
function foodEmoji(name){const warm=/roti|chilla|poha|chana/i.test(name),protein=/egg|chicken|fish|paneer|tofu/i.test(name);return `<svg class="dish" viewBox="0 0 120 120" aria-hidden="true"><ellipse cx="60" cy="101" rx="43" ry="8" fill="#526144" opacity=".09"/><circle cx="60" cy="59" r="49" fill="#faf8ed" stroke="#dfdfcb" stroke-width="3"/><circle cx="60" cy="59" r="40" fill="#ebe9d5"/><path d="M28 63c-2 17 14 32 32 32 10 0 20-4 26-12L59 54Z" fill="${warm?'#ddbd77':'#f5f0cf'}"/><path d="m33 65 25 20m-24-9 20 15m-8-31 22 20m-10-25 21 20" stroke="${warm?'#caa564':'#e1dabb'}" stroke-width="2" stroke-linecap="round"/><ellipse cx="80" cy="50" rx="17" ry="24" fill="${protein?'#c77e52':'#d7a449'}" transform="rotate(-27 80 50)"/><path d="m76 35 12 17m-17-7 15 20" stroke="${protein?'#b3633e':'#bd8d3c'}" stroke-width="3" stroke-linecap="round"/><g fill="#789354"><ellipse cx="37" cy="40" rx="12" ry="16" transform="rotate(-40 37 40)"/><ellipse cx="51" cy="33" rx="11" ry="14" transform="rotate(27 51 33)"/><ellipse cx="47" cy="48" rx="11" ry="13" transform="rotate(53 47 48)"/></g><g fill="#648044"><circle cx="32" cy="34" r="5"/><circle cx="54" cy="28" r="5"/></g><circle cx="86" cy="78" r="10" fill="#c77953"/><circle cx="86" cy="78" r="6" fill="#e6a16d"/><path d="M69 86a12 12 0 0 0 20 6L76 79Z" fill="#e3d577" stroke="#efe49d" stroke-width="2"/></svg>`;}

function weekDates(){const dow=new Date(today()+'T12:00:00').getDay();const monday=shiftDate(today(),-(dow+6)%7);return Array.from({length:7},(_,i)=>shiftDate(monday,i));}
function weekStrip(){return `<div class="week-strip">${weekDates().map(k=>`<button data-action="date" data-date="${k}" class="day-button ${k===selectedDate?'selected':''}"><span>${displayDate(k,{weekday:'short'})}</span><strong>${displayDate(k,{day:'numeric'})}</strong><small>${k===today()?'Today':'•'}</small></button>`).join('')}</div>`;}
function nutrition(){const pl=plan(selectedDate),d=log(selectedDate),used=consumed(d);return title('EAT WELL, FEEL GOOD','Good food. A plan that fits.','Familiar Indian meals, sensible portions, and room for real life.',btn(icon('bag')+' Weekly groceries','grocery','primary'))+weekStrip()+
 (pl.limited?limitedNotice():`<div class="nutrition-summary card"><div><span class="eyebrow">${displayDate(selectedDate,{weekday:'long',day:'numeric',month:'short'}).toUpperCase()} · PLANNED TOTAL</span><h2>${fmt(pl.total.k)} <small>kcal</small> <span>/ ${fmt(pl.calories)} target</span></h2></div><div><strong>${pl.total.p} g</strong><small>Protein / ${pl.protein} g</small></div><div><strong>~₹${pl.total.price}</strong><small>Food cost / ₹${p().budget} budget</small></div><div><strong>${pl.meals.length} meals</strong><small>Prepared around your preferences</small></div></div>${planWarnings(pl)}<div class="meals-grid">${pl.meals.map((m,i)=>mealCard(m,i,selectedDate,d)).join('')}</div><p class="fine-print">All nutrition and costs are approximate. Ingredient weights are dry/raw unless marked; milk is in ml. Cook with the listed oil. Spices, lemon and salt to taste are not costed. Check labels and cross-contact if you have allergies.</p>`)+
 `<section class="card"><div class="section-head"><div><h2>Your food log</h2><p>${used.k} kcal · ${used.p} g protein logged for ${displayDate(selectedDate)}</p></div>${btn(icon('plus')+' Add food','food','secondary',`data-date="${selectedDate}" ${selectedDate>today()?'disabled':''}`)}</div>${d.food.length?`<div class="ledger">${d.food.map((f,i)=>`<div><span><strong>${esc(f.name)}</strong><small>${f.slot?cap(f.slot):'Custom entry'}</small></span><span>${f.k} kcal · ${f.p} g</span><button class="text-btn muted" data-action="delete-food" data-index="${i}" data-date="${selectedDate}" aria-label="Remove ${esc(f.name)}">${icon('close')}</button></div>`).join('')}</div>`:'<p class="muted">Nothing logged yet. Mark a meal as eaten or add your own food.</p>'}</section>`;
}
function planWarnings(pl){const warnings=[];if(pl.meals.length<4)warnings.push('Some meals are unavailable with these exclusions. Add a custom meal or adjust your exclusions.');if(pl.total.price>p().budget)warnings.push(`This plan is approximately ₹${pl.total.price-p().budget} above your daily budget. Swap meals for cheaper choices; prices vary locally.`);if(pl.total.p<pl.protein*.9)warnings.push(`This menu provides ${pl.total.p} g protein, below your ${pl.protein} g estimate. Review protein-rich alternatives or add a suitable snack.`);if(Math.abs(pl.total.k-pl.calories)>pl.calories*.12)warnings.push('The menu calories differ from your estimated target. Use portions and custom food logging to adjust, rather than treating this as an exact prescription.');return warnings.length?`<div class="notice subtle"><div>${warnings.map(w=>`<p>${w}</p>`).join('')}</div></div>`:'';}
function mealCard(m,i,key,d){const eaten=d.food.some(x=>x.slot===m.slot);return `<article class="card meal-card"><div class="meal-visual visual-${i}"><span class="tag">${cap(m.slot)}</span><div aria-hidden="true">${foodEmoji(m.name)}</div><span class="prep-time">${icon('clock')} ${m.minutes} min</span></div><div class="meal-body"><h3>${m.name}</h3><div class="macro-line"><span>${m.k} kcal</span><b>${m.p} g protein</b><span>~₹${m.price}</span></div><ul class="ingredients-preview">${Object.entries(m.ingredients).slice(0,3).map(([id,g])=>`<li>${quantity(id,g)} ${FOODS[id].name}</li>`).join('')}</ul><div class="meal-actions">${btn('View recipe','recipe','text-btn',`data-slot="${m.slot}" data-date="${key}"`)}${btn(icon('swap')+' Swap','swap','text-btn',`data-slot="${m.slot}" data-date="${key}"`)}</div>${btn(eaten?icon('check')+' Eaten · undo':'Mark as eaten','eat-meal',eaten?'secondary full':'primary full',`data-slot="${m.slot}" data-date="${key}" ${key>today()?'disabled':''}`)}</div></article>`;}
function quantity(id,g){return id==='egg'?`${g/50} egg${g>50?'s':''} (~${g} g)`:`${g} ${FOODS[id].unit||'g'}`;}
function training(){const w=workout(p(),today(),previous(today())),d=log();return title('MOVE WITH PURPOSE','Stronger, one session at a time.','A home routine built around your experience, equipment, and available time.',btn(icon('clock')+' Rest timer','timer','secondary'))+`<div class="week-strip training-week">${weekDates().map(k=>{const ww=workout(p(),k,previous(k));return `<div class="day-button ${k===today()?'selected':''}"><span>${displayDate(k,{weekday:'short'})}</span>${icon(ww.rest?'leaf':'weight')}<small>${state.logs[k]?.workout?'Logged':ww.rest?'Recover':'Strength'}</small></div>`;}).join('')}</div><div class="training-layout"><section><div class="card training-banner"><span class="eyebrow">TODAY · ${p().level.toUpperCase()} · ${p().equipment.toUpperCase()}</span><h2>${w.title}</h2><p>${w.note}</p><div class="chips"><span>${icon('clock')} ${w.minutes} minutes</span><span>${icon('weight')} ${w.exercises.length||'Gentle'} ${w.rest?'movement':'exercises'}</span></div></div>${w.rest?`<section class="card recovery-card">${icon('leaf')}<h2>Give yourself room to recover.</h2><p>${targets(p()).limited?'Follow your clinician’s guidance for activity.':'Try an easy 10–20 minute walk and gentle, pain-free movement. Skip anything that hurts. A recovery day is part of the plan.'}</p>${btn(d.workout?icon('check')+' Movement logged · undo':'Log comfortable movement','complete-workout','primary')}</section>`:`<div class="warmup"><strong>Before you begin</strong><span>3–5 minutes of easy marching, shoulder circles and comfortable bodyweight movements. Stop for pain, dizziness or chest discomfort.</span></div>${w.exercises.map((e,i)=>`<article class="card exercise"><span class="exercise-number">0${i+1}</span><div class="exercise-content"><h3>${e.name}</h3><p>${e.cue}</p><div class="exercise-details"><span><strong>${e.sets}</strong> sets</span><span><strong>${e.reps}</strong> reps</span><button class="text-btn" data-action="timer" data-seconds="${e.rest}">${icon('clock')} ${e.rest}s rest</button></div></div><button class="exercise-check ${d.exercise.includes(e.id)?'checked':''}" data-action="exercise" data-id="${e.id}" aria-label="Mark ${e.name} completed" aria-pressed="${d.exercise.includes(e.id)}">${icon('check')}</button></article>`).join('')}<div class="session-finish">${btn(d.workout?icon('check')+' Session logged · undo':'Finish & log session','complete-workout','primary')}<p>Log when you finish. Adjust or skip exercises as needed.</p></div>`}</section><aside><section class="card training-notes"><span class="soft-icon green">${icon('spark')}</span><h3>Make the reps count.</h3><p>Strength days are Monday, Wednesday and Friday, with recovery between sessions.</p><p>Move slowly and comfortably. End each set with 2–3 good repetitions still possible.</p><hr><h4>Your next progression</h4><p>${p().level==='beginner'?'Learn the movement first. When all sets feel comfortable, add one repetition per set.':p().equipment==='bodyweight'?'Add a repetition, slow the lowering phase, or use a slightly harder variation you can perform comfortably.':'Reach the top of the rep range with good form, then use a small increase in resistance.'}</p><hr><h4>Room to breathe</h4><p>Rest ${['lean_bulk','muscle_gain'].includes(p().goal)?90:60} seconds, or longer if you need it. Include 2–3 minutes of an easy cooldown. Time estimates include warm-up and rest; stop at your time limit.</p></section><section class="card soft-green"><h3>Beyond the workout</h3><p>Build gradually toward 150 minutes of moderate activity each week, plus strength work on at least 2 days. Short walks count too.</p><a class="text-link" href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener">Activity guidance ${icon('arrow')}</a></section></aside></div>`;}
function chart(metric){const entries=state.measurements.filter(x=>x[metric]>0).sort((a,b)=>a.date.localeCompare(b.date)).slice(-20);if(entries.length<2)return empty('Every journey starts somewhere.','Add measurements on at least two dates to see your trend.',btn('Log a measurement','measurement','secondary'));const values=entries.map(x=>x[metric]),min=Math.min(...values)-1,max=Math.max(...values)+1,W=660,H=220,x=i=>50+i*(W-75)/(entries.length-1),y=v=>20+(max-v)/(max-min)*(H-55),points=entries.map((e,i)=>`${x(i)},${y(e[metric])}`).join(' ');return `<svg class="progress-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${metric} trend from ${entries[0][metric]} to ${entries.at(-1)[metric]}">${[0,1,2,3].map(i=>{let v=min+(max-min)*i/3;return `<path d="M50 ${y(v)}H645" stroke="#e7ebe3"/><text x="0" y="${y(v)+4}" fill="#718074" font-size="12">${v.toFixed(1)}</text>`;}).join('')}<polygon points="50,185 ${points} 635,185" fill="#e6eedb" opacity=".55"/><polyline points="${points}" fill="none" stroke="#537351" stroke-width="3" stroke-linejoin="round"/>${entries.map((e,i)=>`<circle cx="${x(i)}" cy="${y(e[metric])}" r="4" fill="#537351"><title>${e.date}: ${e[metric]}</title></circle>`).join('')}<text x="50" y="215" fill="#718074" font-size="12">${displayDate(entries[0].date)}</text><text x="635" y="215" text-anchor="end" fill="#718074" font-size="12">${displayDate(entries.at(-1).date)}</text></svg>`;}
function milestone(){const ms=[...state.measurements].sort((a,b)=>a.date.localeCompare(b.date)),start=ms[0]?.weight||p().weight,current=ms.at(-1)?.weight||p().weight,goal=p().targetWeight;const percent=start===goal?0:Math.max(0,Math.min(100,(current-start)/(goal-start)*100));if(p().goal==='maintain')return `<section class="card milestone"><div class="section-head"><h2>Consistency is your milestone</h2><span>Maintenance journey</span></div><p>Keep an eye on your usual range, strength and energy. Your latest recorded weight is ${current} kg; your reference target is ${goal} kg.</p></section>`;return `<section class="card milestone"><div class="section-head"><div><h2>Your transformation milestones</h2><p>${start} kg starting point → ${goal} kg personal target</p></div><strong>${Math.round(percent)}%</strong></div>${progress(percent,100)}<div class="milestone-labels">${[25,50,75,100].map(n=>`<span class="${percent>=n?'reached':''}">${percent>=n?'✓ ':''}${n}%<small>${+(start+(goal-start)*n/100).toFixed(1)} kg</small></span>`).join('')}</div><p class="fine-print">Weight fluctuates. This shows the latest measurement relative to your own target, not a health score or a promised timeline.</p></section>`;}
function progressPage(){const ms=[...state.measurements].sort((a,b)=>a.date.localeCompare(b.date)),last=ms.at(-1),first=ms[0],checks=Object.values(state.logs).filter(x=>x.checkin).length,sessions=Object.values(state.logs).filter(x=>x.workout).length;return title('THE BIGGER PICTURE','Your effort is adding up.','Look for the trend. Celebrate the habits behind the numbers.',btn(icon('plus')+' Log measurement','measurement','primary'))+`<div class="progress-stats"><section class="card"><span>Starting weight</span><strong>${first?.weight||p().weight} <small>kg</small></strong></section><section class="card"><span>Latest weight</span><strong>${last?.weight||p().weight} <small>kg</small></strong></section><section class="card"><span>Your target</span><strong>${p().targetWeight} <small>kg</small></strong></section><section class="card"><span>Check-in streak</span><strong>${streak(state.logs,today())} <small>days</small></strong></section></div>${milestone()}<div class="two-columns"><section class="card"><div class="section-head"><h2>Weight trend <small>kg</small></h2><span class="tag">Last 20 entries</span></div>${chart('weight')}</section><section class="card"><div class="section-head"><h2>Waist trend <small>cm</small></h2></div>${chart('waist')}</section></div><section class="card"><div class="section-head"><h2>Wins beyond the scale</h2><span>Every small promise kept</span></div><div class="achievements">${[[checks>=1,'First step','Your first check-in','spark'],[checks>=7,'Showing up','7 total check-ins','sun'],[sessions>=5,'Getting stronger','5 logged sessions','weight'],[streak(state.logs,today())>=7,'A week of you','7-day check-in streak','fire']].map(([yes,t,s,ic])=>`<div class="achievement ${yes?'unlocked':''}"><span>${icon(ic)}</span><h3>${t}</h3><p>${s}</p><small>${yes?'Achieved':'In progress'}</small></div>`).join('')}</div></section><section class="card"><div class="section-head"><div><h2>Your visual journal</h2><p>For you, by you. Photos stay in this browser.</p></div>${btn(icon('camera')+' Add photo','photo','secondary')}</div>${state.photos.length?`<div class="photos">${state.photos.map((ph,i)=>`<figure><img src="${ph.data}" alt="Progress photo ${esc(ph.date)}"><figcaption><span><strong>${i===0?'Your starting point':i===state.photos.length-1?'Your latest chapter':'Along the way'}</strong>${displayDate(ph.date)} · ${esc(ph.note)}</span><button class="text-btn" data-action="delete-photo" data-index="${i}" aria-label="Delete photo">${icon('close')}</button></figcaption></figure>`).join('')}</div>`:empty('A story only you can tell.','Add a starting photo, then another whenever you feel ready. No pressure, no comparison.')}</section><section class="card"><div class="section-head"><h2>Measurement history</h2><span>Nutrition targets stay stable until you update your profile.</span></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Weight</th><th>Waist</th><th>Hips</th><th>Chest</th><th></th></tr></thead><tbody>${ms.slice().reverse().map(m=>`<tr><td>${displayDate(m.date)}</td><td>${m.weight} kg</td><td>${m.waist||'—'} cm</td><td>${m.hips||'—'} cm</td><td>${m.chest||'—'} cm</td><td><button class="text-btn" data-action="delete-measurement" data-date="${m.date}" aria-label="Delete measurement for ${m.date}">${icon('close')}</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function mentorPage(){const m=mentor(p(),state.logs,today()),t=targets(p()),recent=Object.entries(state.logs).filter(([,d])=>d.checkin).sort(([a],[b])=>b.localeCompare(a)).slice(0,7);return title('A LITTLE GUIDANCE','You don’t have to figure it all out.','Thoughtful prompts, practical choices, and a plan that listens.')+`<section class="mentor-hero"><span class="soft-icon">${icon('spark')}</span><div><span class="eyebrow">YOUR DAILY GUIDANCE</span><h2>${esc(m.title)}</h2><p>${esc(m.text)}</p>${btn('What should I eat now? '+icon('arrow'),'eat','lime')}</div></section><div class="three-columns"><section class="card"><span class="soft-icon green">${icon('leaf')}</span><h3>Prefer the everyday staples</h3><p>Dal, beans, seasonal vegetables, fruit, whole grains and a protein source you enjoy. Balance and variety beat expensive “fitness” foods.</p></section><section class="card"><span class="soft-icon peach">${icon('heart')}</span><h3>Limit, don’t label</h3><p>Keep sugary drinks, frequent deep-fried snacks and alcohol occasional. No food needs a guilt label. Your overall pattern matters.</p></section><section class="card"><span class="soft-icon purple">${icon('moon')}</span><h3>Recovery is part of the work</h3><p>Protect a regular bedtime and your ${p().sleep}-hour sleep goal. Low energy or high soreness in a check-in makes tomorrow a recovery day.</p></section></div><section class="card"><div class="section-head"><h2>Your personal starting points</h2>${btn('How we calculate','method','text-btn')}</div><div class="progress-stats no-gap"><div><span>BMI estimate</span><strong>${t.bmi}</strong><small>A screening measure, not a diagnosis.</small></div><div><span>BMR estimate</span><strong>${t.bmr}<small> kcal</small></strong><small>Energy at rest.</small></div><div><span>Maintenance estimate</span><strong>${t.maintenance}<small> kcal</small></strong><small>Includes your activity setting.</small></div><div><span>Daily goal estimate</span><strong>${t.calories||'Paused'}<small>${t.calories?' kcal':''}</small></strong><small>Review after 2–4 consistent weeks.</small></div></div></section><section class="card"><div class="section-head"><h2>Your recent reflections</h2>${btn('Check in','checkin','secondary')}</div>${recent.length?`<div class="reflections">${recent.map(([key,d])=>`<div><span class="soft-icon green">${icon('heart')}</span><div><strong>${displayDate(key)} · Energy ${d.checkin.energy}/5</strong><p>Food: ${d.checkin.diet==='hard'?'needed support':'felt manageable'} · Soreness: ${d.checkin.soreness} · Workout: ${esc(d.checkin.workout||'not recorded')}${d.checkin.note?' · '+esc(d.checkin.note):''}</p></div></div>`).join('')}</div>`:empty('A minute to listen to yourself.','Your check-ins help shape tomorrow. Low recovery eases training; difficult food days prioritize quicker meals.')}</section><p class="fine-print">Forma uses a local rules-based mentor, not a live coach or AI chat. It does not diagnose conditions or guarantee a transformation timeline.</p>`;}
function settings(){return title('MAKE IT YOURS','Your journey, your preferences.','Update your starting points or keep a copy of what you’ve built.')+`<section class="card"><div class="section-head"><h2>Your personal plan</h2>${btn('Edit profile','profile','primary')}</div><div class="profile-summary">${[['Goal',GOALS[p().goal]],['Food preference',p().diet],['Daily food budget',`₹${p().budget}`],['Training',`${p().level} · ${p().equipment}`],['Available time',`${p().time} minutes`],['Food exclusions',p().allergies.join(', ')||'None selected'],['Avoid ingredients',p().avoid||'None']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div></section><div class="two-columns"><section class="card"><span class="soft-icon green">${icon('download')}</span><h2>Keep your progress safe</h2><p>Everything is saved on this browser and device. Clearing browser data removes it. Export a backup regularly; restore it to move to another device.</p><div class="actions">${btn('Export backup','export','primary')}${btn('Restore backup','restore','secondary')}</div><p class="fine-print">Backups include health details and photos, and are not encrypted. Keep them somewhere private. There are no accounts, cloud sync, or owner access to visitors’ data.</p></section><section class="card"><span class="soft-icon blue">${icon('book')}</span><h2>Understand your plan</h2><p>Meal nutrition, prices and calorie needs are estimates. Formula inputs and the plan’s practical limits are explained in one place.</p>${btn('Method & sources','method','secondary')}<hr><p>For adults 18–80. Personalized planning pauses for selected health considerations or a low current/target BMI.</p></section></div><section class="card danger-zone"><div><h3>Start fresh on this device</h3><p>Remove your profile, logs, measurements and photos from this browser.</p></div>${btn('Delete my data','reset','danger')}</section>`;}

// Dialogs use native focus trapping and restore focus on close.
let lastFocus;
function showModal(title,body,wide=false){const dialog=$('#modal');lastFocus=document.activeElement;dialog.className=wide?'wide':'';dialog.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="text-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.querySelector('input,select,button,textarea')?.focus();}
function closeModal(){$('#modal').close();if(lastFocus?.isConnected)lastFocus.focus();}
function field(label,name,value,type='number',attrs=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function select(label,name,options,value){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function setup(edit=false){draft={...(edit?p():DEFAULT_PROFILE),allergies:[...(edit?p().allergies:[])]};setupStep=0;setupDialog();}
function setupDialog(){let content='';if(setupStep===0)content=`<p>Let’s build around you. These details help estimate a starting point.</p><div class="form-grid">${field('What should we call you?','name',draft.name,'text','maxlength="40" placeholder="Your first name"')}${field('Age','age',draft.age,'number','min="18" max="80" required')}${select('Gender (optional)','gender',[['prefer','Prefer not to say'],['woman','Woman'],['man','Man'],['nonbinary','Non-binary'],['self','Self-described']],draft.gender)}${select('Sex used in calorie formula','sex',[['male','Male equation'],['female','Female equation']],draft.sex)}${field('Height · cm','height',draft.height,'number','min="120" max="230" required')}${field('Current weight · kg','weight',draft.weight,'number','min="35" max="250" step="0.1" required')}</div><p class="fine-print">The calorie equation uses a sex-specific coefficient; gender does not determine this choice. Both are rough estimates and may be less suitable during hormone therapy.</p><label class="check-field"><input type="checkbox" name="health" ${draft.health?'checked':''}><span>I am pregnant/breastfeeding, have a relevant medical condition, an injury affecting exercise, an eating-disorder history, or need a clinician-set plan.</span></label><p class="fine-print">If selected, Forma provides habit tracking without automated nutrition or exercise prescriptions.</p>`;
 if(setupStep===1)content=`<p>A plan should work with your life, including your kitchen and budget.</p><div class="form-grid">${select('Your goal','goal',Object.entries(GOALS),draft.goal)}${field('Target weight · kg','targetWeight',draft.targetWeight,'number','min="35" max="250" step="0.1" required')}${select('Usual activity','activity',[[1.2,'Mostly seated'],[1.375,'Lightly active'],[1.55,'Moderately active'],[1.725,'Very active']],draft.activity)}${select('Food preference','diet',[['veg','Vegetarian (includes dairy)'],['eggetarian','Eggetarian'],['nonveg','Non-vegetarian']],draft.diet)}${field('Food budget per day · ₹','budget',draft.budget,'number','min="60" max="1500" required')}${field('Avoid ingredients · comma-separated','avoid',draft.avoid,'text','maxlength="200" placeholder="e.g. paneer, banana"')}</div><fieldset><legend>Exclude these food groups</legend><div class="checkbox-group">${[['dairy','Dairy'],['gluten','Gluten / wheat'],['soy','Soy'],['peanut','Peanuts'],['egg','Eggs'],['fish','Fish']].map(([v,l])=>`<label><input type="checkbox" name="allergies" value="${v}" ${draft.allergies.includes(v)?'checked':''}>${l}</label>`).join('')}</div></fieldset><p class="fine-print">Filters cover listed ingredients, not manufacturing cross-contact or all possible allergens. Verify packaged foods. Cost estimates use editable sample prices.</p>`;
 if(setupStep===2)content=`<p>Make movement something you can come back to, not something you have to catch up on.</p><div class="form-grid">${select('Training experience','level',[['beginner','Beginner'],['intermediate','Intermediate'],['advanced','Advanced']],draft.level)}${select('Equipment available','equipment',[['bodyweight','Bodyweight only'],['bands','Resistance bands'],['dumbbells','Dumbbells']],draft.equipment)}${select('Time per session','time',[[15,'15 minutes'],[20,'20 minutes'],[30,'30 minutes'],[45,'45 minutes'],[60,'60 minutes']],draft.time)}${field('Daily step goal','steps',draft.steps,'number','min="1000" max="25000" step="500" required')}${field('Sleep goal · hours','sleep',draft.sleep,'number','min="6" max="10" step="0.5" required')}</div><div class="notice subtle"><div><strong>A starting point, not a promise.</strong><p>Targets are estimates. Your check-ins guide lighter recovery days and easier meals. Review long-term trends before changing your nutrition targets.</p></div></div><label class="check-field"><input type="checkbox" name="consent" required><span>I understand this is general adult wellness guidance, and that my data is saved only in this browser.</span></label>`;
 showModal(state.profile?'Refine your personal plan':'Let’s get to know you',`<div class="setup-progress">${['About you','Food & goals','Movement'].map((s,i)=>`<span class="${setupStep>=i?'active':''}">${i+1}<small>${s}</small></span>`).join('')}</div><form id="setup-form">${content}<div id="form-error" class="form-error" role="alert"></div><div class="form-actions">${setupStep?btn('Back','setup-back','secondary'):'<span>About 2 minutes. Entirely yours.</span>'}<button type="submit" class="btn primary">${setupStep===2?'Create my plan':'Continue'} ${icon('arrow')}</button></div></form>`,true);
}
function recipeDialog(slot,key){const m=plan(key).meals.find(x=>x.slot===slot);if(!m)return;modalContext={slot,key};showModal(m.name,`<div class="recipe-top"><span class="food-emoji">${foodEmoji(m.name)}</span><div><span class="tag">${cap(m.slot)} · ${m.minutes} min</span><h3>${m.k} kcal · ${m.p} g protein</h3><p>${m.c} g carbs · ${m.f} g fat · ~₹${m.price}</p></div></div><h3>Your ingredients</h3><div class="ingredient-list">${Object.entries(m.ingredients).map(([id,g])=>`<div><span><strong>${FOODS[id].name}</strong><small>${quantity(id,g)}</small></span>${btn('Alternatives','replacements','text-btn',`data-id="${id}" data-g="${g}"`)}</div>`).join('')}</div><h3>Make it at home</h3><p>${m.method}</p><p class="fine-print">Dry/raw weights before cooking unless named otherwise. Approximate nutrition includes the listed oil. Spices and lemon to taste.</p>${btn(icon('swap')+' Choose another meal','swap','secondary',`data-slot="${slot}" data-date="${key}"`)}`);}
function swapDialog(slot,key){const t=targets(p());if(t.limited)return;const i=SLOTS.indexOf(slot),f=[.25,.3,.15,.3][i];let options=mealOptions(p(),slot,t.calories*f,t.protein*f,p().budget*f);if(previous(key)?.diet==='hard')options.sort((a,b)=>a.minutes-b.minutes);showModal(`Find your ${slot} alternative`,`<p>Choose what works for your kitchen today. The grocery list updates with your selection.</p><div class="swap-list">${options.map((m,i)=>`<button data-action="choose-swap" data-index="${i}" data-slot="${slot}" data-date="${key}"><span class="food-emoji">${foodEmoji(m.name)}</span><span><strong>${m.name}</strong><small>${m.k} kcal · ${m.p} g protein · ~₹${m.price}</small></span>${icon('arrow')}</button>`).join('')}</div>`);}
function groceryDialog(){const dates=weekDates(),items=grocery(dates.map(k=>plan(k))),cost=items.reduce((a,x)=>a+x.cost,0);modalContext={groceries:items,dates};showModal('Your weekly grocery list',`<p>${displayDate(dates[0])}–${displayDate(dates[6])} · Matches the 7 daily meal plans, including your swaps.</p><div class="grocery-total"><strong>~₹${fmt(cost)}</strong><span>Estimated ingredient cost · Budget ₹${fmt(p().budget*7)}</span></div><p class="fine-print">Quantities are ingredient weights, not pack sizes. Buy enough packs to cover these amounts. Costs exclude spices and wastage; local prices differ.</p>${items.length?`<div class="grocery-list">${items.map((f,i)=>`${i===0||f.group!==items[i-1].group?`<h3>${f.group}</h3>`:''}<label><input type="checkbox" data-grocery="${dates[0]}:${f.id}" ${state.groceryChecked[dates[0]+':'+f.id]?'checked':''}><span>${f.name}</span><strong>${quantity(f.id,f.quantity)}</strong></label>`).join('')}</div>${btn(icon('download')+' Download list','download-grocery','primary full')}`:empty('No automated meal plan','Your current profile is in habit tracking mode.')}`,true);}
function checkinDialog(){const c=log().checkin||{energy:3,soreness:'low',diet:'okay',sleep:log().sleep||'',workout:log().workout?'done':'not_yet',note:''};showModal('A minute for yourself',`<p>How did today feel? Your answers gently shape tomorrow’s plan.</p><form id="checkin-form"><div class="field"><span>Energy today</span><div class="energy-options">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="energy" value="${n}" ${+c.energy===n?'checked':''}><span><svg width="28" height="28" viewBox="0 0 28 28" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="14" cy="14" r="11"/><path d="M10 10h1m6 0h1 M9 ${n<=2?'19q5-5 10 0':n===3?'18h10':'16q5 7 10 0'}"/></svg><small>${n}/5</small></span></label>`).join('')}</div></div><div class="form-grid">${select('Following the food plan felt…','diet',[['okay','Manageable'],['hard','Difficult — make it simpler']],c.diet)}${select('Muscle soreness','soreness',[['low','Low'],['moderate','Moderate'],['high','High']],c.soreness)}${field('Last night’s sleep · hours','sleep',c.sleep,'number','min="0" max="16" step="0.25" required')}${select('Today’s workout','workout',[['done','Completed'],['partial','Partly completed'],['rest','Recovery / rest day'],['not_yet','Not completed']],c.workout)}</div><label class="field"><span>Anything you’d like to remember?</span><textarea name="note" maxlength="500" rows="3" placeholder="One win, one challenge…">${esc(c.note)}</textarea></label><p class="fine-print">Energy 1–2, high soreness, or less than 6 hours of sleep makes tomorrow a recovery day. Difficult food days prioritize quicker meals. Calories aren’t cut to compensate.</p><button class="btn primary full">Save my check-in ${icon('check')}</button></form>`);}
function habitsDialog(){const d=log();showModal('A little more balance',`<form id="habits-form"><div class="form-grid">${field('Steps today','steps',d.steps,'number','min="0" max="100000" required')}${field('Last night’s sleep · hours','sleep',d.sleep,'number','min="0" max="16" step="0.25" required')}${field('Water today · ml','water',d.water,'number','min="0" max="10000" step="50" required')}</div><p class="fine-print">These are manual entries. Water needs vary with heat and activity; follow any fluid restriction set by your clinician.</p><button class="btn primary full">Save daily totals</button></form>`);}
function foodDialog(key=today()){showModal('Add to your food log',`<p>${displayDate(key)} · Use a package label or your best estimate.</p><form id="food-form" data-date="${key}">${field('Food / meal name','name','','text','required maxlength="100" placeholder="e.g. Homemade vegetable sandwich"')}<div class="form-grid">${field('Calories · kcal','k','','number','min="0" max="5000" required')}${field('Protein · g','p','','number','min="0" max="400" step="0.1" required')}</div><button class="btn primary full">Log food</button></form>`);}
function eatDialog(){if(targets(p()).limited){foodDialog();return;}const hour=new Date().getHours(),slot=hour<11?'breakfast':hour<15?'lunch':hour<18?'snack':'dinner';showModal('What should I eat now?',`<p>Let’s find a useful next meal, using your logged food and preferences.</p><form id="recommend-form"><div class="form-grid">${select('Meal you’re looking for','slot',SLOTS.map(x=>[x,cap(x)]),slot)}${field('Budget for this meal · ₹','budget',Math.max(30,Math.round(p().budget*.3)),'number','min="10" max="1500" required')}${field('Ingredients you don’t have','unavailable','','text','maxlength="200" placeholder="e.g. rice, paneer"')}</div><button class="btn primary full">Find a meal ${icon('spark')}</button></form><div id="recommend-results"></div>`);}
let recommendations=[];
function recommend(form){const f=new FormData(form),t=targets(p()),used=consumed(log()),remainingK=Math.max(0,t.calories-used.k),remainingP=Math.max(0,t.protein-used.p),budget=+f.get('budget'),slot=f.get('slot'),exclusions=[p().avoid,f.get('unavailable')].filter(Boolean).join(',');const plannedSlots=new Set(log().food.map(x=>x.slot));const count=Math.max(1,SLOTS.filter(s=>!plannedSlots.has(s)).length);const mealK=remainingK?Math.max(200,Math.min(slot==='snack'?450:800,remainingK/count)):slot==='snack'?250:450;recommendations=mealOptions({...p(),avoid:exclusions},slot,mealK,Math.min(45,remainingP/count),budget).slice(0,3);
 $('#recommend-results').innerHTML=`<div class="notice subtle"><p>${remainingK?`${fmt(remainingK)} kcal and ${remainingP} g protein remain against today’s estimate.`:'You’ve reached your calorie estimate. If you’re hungry, a balanced meal is still okay; targets aren’t hard limits.'}</p></div>${recommendations.length?recommendations.map((m,i)=>`<div class="recommendation"><h3>${m.name}</h3><p>${m.k} kcal · ${m.p} g protein · ~₹${m.price}${m.price>budget?' · Above this meal budget':''}</p><p class="fine-print">${Object.entries(m.ingredients).map(([id,g])=>quantity(id,g)+' '+FOODS[id].name).join(' · ')}</p><details><summary>Preparation</summary><p>${m.method}</p></details>${btn('I ate this — log it','log-recommendation','secondary',`data-index="${i}"`)}</div>`).join(''):empty('No match with these ingredients','Try another meal type, remove an unavailable ingredient, or log your own meal.')}`;
}
function measurementDialog(){showModal('A new point in your journey',`<form id="measurement-form"><div class="form-grid">${field('Date','date',today(),'date',`max="${today()}" required`)}${field('Weight · kg','weight',state.measurements.at(-1)?.weight||p().weight,'number','min="35" max="250" step="0.1" required')}${field('Waist · cm (optional)','waist','','number','min="30" max="250" step="0.1"')}${field('Hips · cm (optional)','hips','','number','min="30" max="250" step="0.1"')}${field('Chest · cm (optional)','chest','','number','min="30" max="250" step="0.1"')}</div><p class="fine-print">One entry per date; saving on an existing date replaces that measurement. Use similar timing and conditions for more useful trends.</p><button class="btn primary full">Save measurement</button></form>`);}
function photoDialog(){showModal('Your visual journal',`<p>Add a photo whenever you feel ready. Up to 12 compressed photos are stored locally.</p><form id="photo-form">${field('Photo date','date',today(),'date',`max="${today()}" required`)}${field('A note (optional)','note','','text','maxlength="100" placeholder="e.g. Week 1, feeling motivated"')}<label class="field"><span>Choose a photo · JPEG, PNG or WebP · max 10 MB</span><input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><div id="photo-error" class="form-error" role="alert"></div><button class="btn primary full">Save photo</button></form>`);}
function timerDialog(seconds=60){showModal('Take a breath',`<p>Let your breathing settle before the next set.</p><div id="timer-display" class="timer-display">${seconds}</div><div class="actions center">${btn('Start '+seconds+'s','start-timer','primary',`data-seconds="${seconds}"`)}${btn('Reset','reset-timer','secondary',`data-seconds="${seconds}"`)}</div><p class="fine-print">The timer uses elapsed time, even if this tab is in the background. Rest longer when needed.</p>`);if(timerEnd)tickTimer();}
function tickTimer(){const el=$('#timer-display');if(!el)return;const remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));el.textContent=remaining?`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`:'Ready when you are';if(remaining===0){timerEnd=0;clearInterval(timerInterval);}}
function methodDialog(){showModal('How your plan is made',`<div class="method-copy"><h3>A practical starting point</h3><p>BMR uses the Mifflin–St Jeor equation: 10 × weight (kg) + 6.25 × height (cm) − 5 × age, then +5 for the male equation or −161 for the female equation. Maintenance multiplies this by the selected activity factor (1.2, 1.375, 1.55 or 1.725).</p><p>Forma’s planning choices: fat loss uses a 15% deficit capped at 350 kcal; lean bulk adds 150 kcal; muscle gain adds 250 kcal; maintenance adds none. A 1,200/1,500 kcal floor prevents very low automated estimates, but is not a clinical safety guarantee. Protein is estimated at 1.2 g/kg for maintenance and 1.6 g/kg for other goals. These are adjustable starting assumptions in the code, not a prescription.</p><p>Water starts at 30 ml/kg, bounded to 1.8–3.5 L and rounded to a 250 ml glass. Actual needs vary. Follow clinical fluid advice where applicable.</p><h3>Food and cost estimates</h3><p>A curated ingredient table estimates nutrition per 100 g/ml. Quantities are dry/raw unless named otherwise. Recipes are scaled to approximate meal targets, with practical limits on portions. Prices are sample Indian ingredient costs, not live market prices. Menus can miss calorie/protein or budget targets; the app shows those gaps. Review package labels and local prices.</p><h3>Adaptation you can understand</h3><p>Yesterday’s low energy (1–2), high soreness, or sleep under 6 hours triggers recovery today. Difficult meal adherence favors shorter recipes. No check-in changes calorie goals or penalizes missed meals. Profile edits regenerate current plans; already logged food keeps its original calories/protein.</p><h3>Who this is for</h3><p>Adults 18–80 using general wellness guidance. Planning pauses for flagged health considerations or current/target BMI below 18.5. BMI is a limited screening measure and does not describe muscle mass or individual health. Consult a qualified professional when targets or exercise suitability are uncertain.</p><h3>Sources & reading</h3><ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener">Mifflin et al. — resting energy estimation</a></li><li><a href="https://www.niddk.nih.gov/health-information/weight-management/body-weight-planner" target="_blank" rel="noopener">NIDDK — adult body weight planning and limitations</a></li><li><a href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener">CDC — adult physical activity guidance</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/28698222/" target="_blank" rel="noopener">Morton et al. — protein supplementation and resistance training</a></li></ul><p>Forma is a rules-based planning tool. It has no generative AI service, clinician review, diagnosis or guaranteed outcomes.</p></div>`,true);}

// A strict backup allow-list prevents malformed state and arbitrary image URLs.
function validBackup(s){try{if(!s||s.version!==1||!s.profile||validateProfile(s.profile).length||typeof s.profile.health!=='boolean')return false;const date=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&dateKey(new Date(v+'T12:00:00'))===v;const num=(v,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=max;const obj=v=>v&&typeof v==='object'&&!Array.isArray(v);if(!obj(s.logs)||!obj(s.swaps)||!obj(s.groceryChecked)||!date(s.started)||!Array.isArray(s.measurements)||!Array.isArray(s.photos)||s.photos.length>12)return false;
 if(Object.keys(s.logs).length>20000||s.measurements.length>20000)return false;
 for(const [key,l] of Object.entries(s.logs)){if(!date(key)||!Array.isArray(l.food)||l.food.length>100||!num(l.water,10000)||!num(l.steps,100000)||!num(l.sleep,16)||!Array.isArray(l.exercise)||l.exercise.some(x=>typeof x!=='string'||x.length>50)||typeof l.workout!=='boolean')return false;for(const f of l.food)if(typeof f.name!=='string'||f.name.length>150||!num(f.k,5000)||!num(f.p,400)||(f.slot&&!SLOTS.includes(f.slot)))return false;if(l.checkin){const c=l.checkin;if(!num(c.energy,5)||c.energy<1||!['okay','hard'].includes(c.diet)||!['low','moderate','high'].includes(c.soreness)||!num(c.sleep,16)||!['done','partial','rest','not_yet'].includes(c.workout)||typeof c.note!=='string'||c.note.length>500)return false;}}
 for(const m of s.measurements)if(!date(m.date)||!num(m.weight,250)||m.weight<35||['waist','hips','chest'].some(k=>!num(m[k],250)))return false;
 for(const ph of s.photos)if(!date(ph.date)||typeof ph.note!=='string'||ph.note.length>100||typeof ph.data!=='string'||ph.data.length>350000||!/^data:image\/jpeg;base64,[a-zA-Z0-9+/=]+$/.test(ph.data))return false;
 for(const [key,sw]of Object.entries(s.swaps)){if(!date(key)||!obj(sw))return false;for(const [slot,v]of Object.entries(sw))if(!SLOTS.includes(slot)||!Number.isInteger(v)||v<0||v>100)return false;}
 for(const [key,v]of Object.entries(s.groceryChecked))if(!/^\d{4}-\d{2}-\d{2}:[a-z]+$/.test(key)||typeof v!=='boolean')return false;
 return true;}catch{return false;}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function restoreDialog(){showModal('Restore your progress',`<p>Choose a Forma JSON backup. It will replace the data currently saved in this browser.</p><form id="restore-form"><label class="field"><span>Backup file · max 6 MB</span><input type="file" name="backup" accept="application/json,.json" required></label><label class="check-field"><input type="checkbox" required><span>I understand this replaces my current data.</span></label><div id="restore-error" role="alert" class="form-error"></div><button class="btn primary full">Restore backup</button></form>`);}
async function savePhoto(form){const f=new FormData(form),file=f.get('photo');if(state.photos.length>=12)throw Error('Remove an older photo first. The limit is 12.');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Choose a JPEG, PNG or WebP under 10 MB.');const bitmap=await createImageBitmap(file),scale=Math.min(1,720/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let data=canvas.toDataURL('image/jpeg',.72);if(data.length>350000)data=canvas.toDataURL('image/jpeg',.4);if(data.length>350000)throw Error('This photo is too detailed. Please choose a smaller image.');const ph={date:f.get('date'),note:f.get('note'),data};state.photos.push(ph);state.photos.sort((a,b)=>a.date.localeCompare(b.date));if(!save()){state.photos=state.photos.filter(x=>x!==ph);throw Error('Photo could not be saved. Export a backup and free browser space.');}closeModal();render();toast('A new chapter added to your visual journal.');}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,key=b.dataset.date||today();switch(a){
 case 'close':closeModal();break;
 case 'setup':setup();break;case 'profile':setup(true);break;case 'setup-back':captureDraft();setupStep--;setupDialog();break;
 case 'water':mutateLog(d=>d.water=Math.max(0,Math.min(10000,d.water+(+b.dataset.amount))));break;
 case 'habits':habitsDialog();break;case 'checkin':checkinDialog();break;case 'date':selectedDate=key;render();break;
 case 'recipe':recipeDialog(b.dataset.slot,key);break;case 'swap':swapDialog(b.dataset.slot,key);break;
 case 'choose-swap':state.swaps[key]??={};state.swaps[key][b.dataset.slot]=+b.dataset.index;save();closeModal();render();toast('Meal updated. Your grocery list is ready too.');break;
 case 'eat-meal':{const m=plan(key).meals.find(x=>x.slot===b.dataset.slot);if(!m||key>today())return;mutateLog(d=>{if(d.food.some(x=>x.slot===m.slot))d.food=d.food.filter(x=>x.slot!==m.slot);else d.food.push({name:m.name,k:m.k,p:m.p,slot:m.slot});},key);break;}
 case 'replacements':{const options=replacementOptions(b.dataset.id,+b.dataset.g,p());showModal('If you don’t have '+FOODS[b.dataset.id].name,`<p>${FOODS[b.dataset.id].p>=10?'Approximate protein-matched':'Approximate calorie-matched'} portions. Other nutrients can differ. These suggestions do not automatically change your recipe or grocery list.</p><div class="swap-list">${options.map(f=>`<div><strong>${quantity(f.id,f.quantity)} ${f.name}</strong><p>${f.k} kcal · ${f.p} g protein · ~₹${f.price}</p></div>`).join('')||'<p>No suitable match with your food exclusions.</p>'}</div><p>For a fully recalculated meal and grocery list, choose a different recipe using Swap. To record an ingredient substitution you ate, add a custom food entry.</p>${btn('Back to recipe','recipe','secondary',`data-slot="${modalContext.slot}" data-date="${modalContext.key}"`)}`);break;}
 case 'grocery':groceryDialog();break;case 'download-grocery':{const {groceries,dates}=modalContext;download(`Forma-groceries-${dates[0]}.txt`,`FORMA · WEEKLY GROCERY LIST\n${dates[0]} to ${dates[6]}\n\n`+groceries.map(f=>`${quantity(f.id,f.quantity)} ${f.name} (~INR ${f.cost})`).join('\n')+'\n\nDry/raw quantities. Sample prices; excludes spices and pack-size rounding.','text/plain');break;}
 case 'food':foodDialog(key);break;case 'delete-food':mutateLog(d=>d.food.splice(+b.dataset.index,1),key);break;
 case 'eat':eatDialog();break;case 'log-recommendation':{const m=recommendations[+b.dataset.index];if(!m)return;mutateLog(d=>d.food.push({name:m.name,k:m.k,p:m.p}));closeModal();toast('Meal added to today’s food log.');break;}
 case 'exercise':mutateLog(d=>{const id=b.dataset.id;d.exercise=d.exercise.includes(id)?d.exercise.filter(x=>x!==id):[...d.exercise,id];});break;
 case 'complete-workout':mutateLog(d=>d.workout=!d.workout);break;
 case 'timer':timerDialog(+b.dataset.seconds||60);break;case 'start-timer':timerEnd=Date.now()+(+b.dataset.seconds)*1000;clearInterval(timerInterval);timerInterval=setInterval(tickTimer,250);tickTimer();break;case 'reset-timer':timerEnd=0;clearInterval(timerInterval);$('#timer-display').textContent=b.dataset.seconds;break;
 case 'measurement':measurementDialog();break;case 'delete-measurement':state.measurements=state.measurements.filter(m=>m.date!==key);save();render();toast('Measurement removed.');break;
 case 'photo':photoDialog();break;case 'delete-photo':showModal('Delete this photo?',`<p>This removes the photo from this browser. Export a backup first if you want to keep it.</p>${btn('Delete photo','confirm-delete-photo','danger',`data-index="${b.dataset.index}"`)}`);break;case 'confirm-delete-photo':state.photos.splice(+b.dataset.index,1);save();closeModal();render();break;
 case 'method':methodDialog();break;case 'streak':showModal('One day at a time',`<div class="streak-large">${icon('fire')} ${streak(state.logs,today())}</div><h3>Consecutive check-in days</h3><p>Save a daily check-in to build your streak. A missed day resets the count, but it never erases your progress.</p>${btn('Check in today','checkin','primary')}`);break;
 case 'export':download(`Forma-backup-${today()}.json`,JSON.stringify(state,null,2));toast('Backup downloaded. Keep it somewhere private.');break;case 'restore':restoreDialog();break;
 case 'reset':showModal('Start fresh?',`<p>This permanently removes all Forma data saved in this browser. Download a backup if you want to keep it.</p><form id="reset-form"><label class="field"><span>Type DELETE to confirm</span><input name="confirm" pattern="DELETE" required autocomplete="off"></label><button class="btn danger full">Delete all my data</button></form>`);break;
}});
function captureDraft(){const form=$('#setup-form');if(!form)return;const data=new FormData(form);for(const [k,v]of data.entries()){if(k==='allergies'||k==='consent')continue;draft[k]=['age','height','weight','targetWeight','budget','activity','time','steps','sleep'].includes(k)?+v:v;}if(setupStep===0)draft.health=data.has('health');if(setupStep===1)draft.allergies=data.getAll('allergies');}
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=new FormData(form);switch(form.id){
 case 'setup-form':{captureDraft();if(setupStep<2){setupStep++;setupDialog();return;}const errors=validateProfile(draft);if(errors.length){$('#form-error').textContent=errors.join(' ');return;}const isNew=!state.profile;state.profile={...draft};state.swaps={};if(isNew)state.measurements=[{date:today(),weight:draft.weight,waist:0,hips:0,chest:0}];save();closeModal();route='dashboard';location.hash='dashboard';render();toast('Your personal plan is ready. Let’s start small.');break;}
 case 'checkin-form':{const c={energy:+f.get('energy'),diet:f.get('diet'),soreness:f.get('soreness'),sleep:+f.get('sleep'),workout:f.get('workout'),note:f.get('note').trim()};mutateLog(d=>{d.checkin=c;d.sleep=c.sleep;d.workout=c.workout==='done';});closeModal();toast('Check-in saved. Tomorrow’s plan will reflect how you feel.');break;}
 case 'habits-form':mutateLog(d=>{d.steps=+f.get('steps');d.sleep=+f.get('sleep');d.water=+f.get('water');});closeModal();toast('Daily totals updated.');break;
 case 'food-form':mutateLog(d=>d.food.push({name:f.get('name').trim(),k:+f.get('k'),p:+f.get('p')}),form.dataset.date);closeModal();toast('Food logged.');break;
 case 'recommend-form':recommend(form);break;
 case 'measurement-form':{const entry={date:f.get('date'),weight:+f.get('weight'),waist:+f.get('waist'),hips:+f.get('hips'),chest:+f.get('chest')};state.measurements=state.measurements.filter(m=>m.date!==entry.date);state.measurements.push(entry);state.measurements.sort((a,b)=>a.date.localeCompare(b.date));save();closeModal();render();toast('Measurement saved.');break;}
 case 'photo-form':{const button=form.querySelector('button');button.disabled=true;button.textContent='Saving…';try{await savePhoto(form);}catch(error){$('#photo-error').textContent=error.message;button.disabled=false;button.textContent='Save photo';}break;}
 case 'restore-form':try{const file=f.get('backup');if(file.size>6*1024*1024)throw Error('Choose a backup smaller than 6 MB.');const imported=JSON.parse(await file.text());if(!validBackup(imported))throw Error('This file is not a valid Forma v1 backup. No data was changed.');const old=state;state=imported;if(!save()){state=old;throw Error('Not enough browser storage. Your previous data was kept.');}closeModal();route='dashboard';location.hash='dashboard';render();toast('Your progress is back. Welcome home.');}catch(error){$('#restore-error').textContent=error.message||'Could not read this backup.';}break;
 case 'reset-form':if(f.get('confirm')==='DELETE'){localStorage.removeItem(KEY);state={version:1,profile:null,logs:{},measurements:[],photos:[],swaps:{},groceryChecked:{},started:today()};closeModal();render();toast('Data removed from this browser.');}break;
}});
document.addEventListener('change',e=>{if(e.target.dataset.grocery){state.groceryChecked[e.target.dataset.grocery]=e.target.checked;save();}});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'dashboard';render();window.scrollTo(0,0);});
let lastDay=today();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&lastDay!==today()){lastDay=today();selectedDate=today();render();}});
render();if(storageError)toast('Saved data could not be loaded. Restore a backup, or start a new profile.');
